/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type CreateDiaryEntryInput = {
  language: Language;
  notesLanguage: Language;
};

export type DeleteDiaryEntryInput = {
  id: string | number;
};

/** Who wrote a diary comment. */
export type DiaryAuthor =
  /** The person writing the diary. */
  | 'LEARNER'
  /** Claude, as the tutor. */
  | 'TUTOR';

/** What a diary thread is about. */
export type DiaryThreadKind =
  /** An entry-wide note from a review. */
  | 'ENTRY'
  /** A "Help me say…" question and its hints. */
  | 'HELP'
  /** The tutor's verdict on one sentence of a review. */
  | 'SENTENCE';

/** The tutor's verdict on one sentence of a diary entry. */
export type DiaryVerdict =
  /** Right, and reads naturally. */
  | 'CORRECT'
  /** Understandable but unnatural or not quite the right word. */
  | 'IMPROVABLE'
  /** Has a mistake of grammar, vocabulary, spelling or meaning. */
  | 'WRONG';

/** How much of a translation to gloss with per-word definitions (design D2.3). */
export type GlossLevel =
  /** Every content word and set phrase, skipping function words. */
  | 'EVERY'
  /** No glosses at all. */
  | 'NONE'
  /** Only the words worth remarking on: ambiguous, idiomatic or register-carrying ones. */
  | 'NOTABLE';

/** A supported language. */
export type Language =
  /** English */
  | 'EN'
  /** Spanish */
  | 'ES'
  /** Japanese */
  | 'JA';

export type ReplyToDiaryThreadInput = {
  body: string;
  threadId: string | number;
};

export type RequestDiaryHintInput = {
  /** A HELP thread. */
  threadId: string | number;
};

export type ResolveDiaryThreadInput = {
  resolved: boolean;
  threadId: string | number;
};

export type ReviewDiaryEntryInput = {
  body: string;
  id: string | number;
};

export type StartDiaryHelpThreadInput = {
  entryId: string | number;
  /** What the learner wants to say, in their own language. */
  question: string;
};

export type SuggestDiaryTopicsInput = {
  /**
   * What the learner has written so far, saved or not. When it has text, the ideas
   * are follow-ups that build on it rather than fresh topics.
   */
  body?: string | null | undefined;
  language: Language;
  notesLanguage: Language;
};

/** Why a translation failed. Each code has its own user-facing message (design D3.3). */
export type TranslateErrorCode =
  /** The demo's Claude usage budget is used up. */
  | 'BUDGET_EXCEEDED'
  /** The source text is blank. */
  | 'EMPTY_INPUT'
  /** The source text or context is over its length limit. */
  | 'INPUT_TOO_LONG'
  /** The translation was too long to finish. */
  | 'OUTPUT_TOO_LONG'
  /** This session or access code is translating too quickly. */
  | 'RATE_LIMITED'
  /** Claude declined to translate the text. */
  | 'REFUSED'
  /** The source and target languages are the same. */
  | 'SAME_LANGUAGE'
  /** The server's Claude credentials or settings are wrong. */
  | 'SERVICE_MISCONFIGURED'
  /** Claude took too long to respond. */
  | 'TIMEOUT'
  /** Claude returned a server error. */
  | 'UPSTREAM_ERROR'
  /** Claude is temporarily overloaded. */
  | 'UPSTREAM_OVERLOADED'
  /** Claude is rate-limiting requests. */
  | 'UPSTREAM_RATE_LIMITED'
  /** Claude could not be reached. */
  | 'UPSTREAM_UNREACHABLE';

export type TranslateInput = {
  /** The situation: where you are, who is speaking to whom, the desired formality or region. */
  context?: string | null | undefined;
  /** How much of the translation to gloss with per-word definitions. */
  glossLevel?: GlossLevel | null | undefined;
  sourceLanguage: Language;
  sourceText: string;
  targetLanguage: Language;
};

export type UpdateDiaryEntryInput = {
  body?: string | null | undefined;
  id: string | number;
  /** Only while the entry has never been reviewed. */
  language?: Language | null | undefined;
  /** Only while the entry has never been reviewed. */
  notesLanguage?: Language | null | undefined;
};

